// In-workflow constant — for production, load from /scripts/migrations/stage-10/canary-pairs.json via filesystem read if n8n's executeWorkflow context allows.
// For now we inline the pairs (kept short for workflow visibility).
const CASES = [
  { id: 'drm-001', query: 'infrastructure SSH alias hg', expected_top_substr: 'hg' },
  { id: 'drm-002', query: 'Qdrant vector dimensions', expected_top_substr: '768' },
  { id: 'drm-003', query: 'claude-memory-postgres container port', expected_top_substr: '5438' },
  { id: 'drm-004', query: 'n8n claude-memory gateway endpoint', expected_top_substr: '5679' },
  { id: 'drm-005', query: 'Stage 8 dual-write feature flag', expected_top_substr: 'STAGE_8_DUAL_WRITE' },
  { id: 'drm-006', query: 'frontend designer agent purpose', expected_top_substr: 'frontend-designer' },
  { id: 'drm-007', query: 'memory_recall hot tier threshold', expected_top_substr: 'hot' },
  { id: 'drm-008', query: 'Memgraph bolt port', expected_top_substr: '7687' },
  { id: 'drm-009', query: 'BRD-tracker workflow gates', expected_top_substr: 'gate' },
  { id: 'drm-010', query: 'Marc conductor process steps mandatory', expected_top_substr: 'process' },
];
const runId = `drm-${new Date().toISOString().slice(0,10)}-${Math.floor(Math.random()*10000)}`;
return CASES.map(c => ({ json: { ...c, canary_run_id: runId } }));

// Score each case. Hit = top result content contains expected substring (case-insensitive).
const caseInputs = $('Load Canary Pairs').all().map(i => i.json);
const recallResults = $input.all().map(i => i.json);
let hits = 0, lure_fa = 0, unrelated_fa = 0, total = caseInputs.length;
const rows = [];
for (let i = 0; i < caseInputs.length; i++) {
  const c = caseInputs[i];
  const r = recallResults[i] || {};
  const memories = (r.memories || r.results || []);
  const top = memories[0] || {};
  const topContent = String(top.payload?.content || top.content || '').toLowerCase();
  const expectedHit = topContent.includes(String(c.expected_top_substr).toLowerCase());
  if (expectedHit) hits++;
  rows.push({
    canary_run_id: c.canary_run_id,
    query: c.query,
    expected_top_id: null,
    actual_top_id: String(top.id || ''),
    lure_returned: false,
    unrelated_returned: false,
    case_count: total,
  });
}
const hit_rate = total > 0 ? hits/total : 0;
const lure_fa_rate = total > 0 ? lure_fa/total : 0;
const unrelated_fa_rate = total > 0 ? unrelated_fa/total : 0;
// Annotate every row with the aggregate rates.
return rows.map(r => ({ json: { ...r, hit_rate, lure_fa_rate, unrelated_fa_rate } }));
